import { join } from './paths';

export function resolveRef($ref: string, potential: string) {
  let $extra = $ref;
  if (potential) {
    // strip the placeholder segment the bundler leaves when baseUrl is unset
    $extra = '/' + ($ref.split('#')[1] || '').replace(potential.split('#')[1] || '');
    $extra = $extra.split('/undefined').join(''); // FIXME
    $ref = potential;
  }
  return $ref + $extra;
}
